import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/redis7/55-第55章—Sentinel篇-Sentinel故障转移实现解析.md","filePath":"books/redis7/55-第55章—Sentinel篇-Sentinel故障转移实现解析.md","lastUpdated":1794316978000}'),s={name:"books/redis7/55-第55章—Sentinel篇-Sentinel故障转移实现解析.md"};function l(r,e,p,o,S,d){return t(),i("div",null,[...e[0]||(e[0]=[n(`<p>在上一讲中，我们详细介绍了 Sentinel 监控 Redis 主从集群的核心思想，也详细分析了 Sentinel 判定 Redis 服务主观下线和客观下线状态的逻辑。<code>那在 Sentinel 感知到 Master 节点发生客观下线之后，会做什么呢？</code></p><p>我可以先告诉你答案，Sentinel 会选择一个 Slave 节点提升为新 Master 节点，并对外继续提供服务，之后，其他 Slave 节点会与新提升的 Master 节点进行主从复制，这个过程就是我们所说的 <strong>“故障转移（failover）”</strong> 。</p><p>Redis 之所以引入 Sentinel，其最主要的目的就是实现“自动故障转移”，也就是说，无需人为干预，Sentinel 自动完成整个“故障转移（failover）”的流程，这就可以减少运维成本，提升了整个 Redis 服务的可用性。</p><h2 id="failover-状态机" tabindex="-1">failover 状态机 <a class="header-anchor" href="#failover-状态机" aria-label="Permalink to &quot;failover 状态机&quot;">​</a></h2><p>在开始介绍 failover 操作之前，我们先来关注一下 Master 节点对应的 <code>sentinelRedisInstance.failover_state 字段</code>，它是<strong>用来控制 failover 执行流程的核心状态字段</strong>，整个 Sentinel 的 failover 操作是以状态机的方式进行驱动的。</p><p>也就是说，<strong>failover_state 这个状态字段控制着整个 failover 的进程，只有 failover_state 的状态值不断向前推进，failover 操作才能继续向下执行</strong>。</p><p>failover_state 字段的状态机如下图所示：</p><p align="center"><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/535a595d16144b1cab431f007689b815~tplv-k3u1fbpfcp-watermark.image?" alt="image.png"></p><p>为了书写简单，后续 failover_state 状态的枚举值都省略“SENTINEL_FAILOVER_STATE_”前缀。下面是 failover_state 在不同状态值所表示的含义，小伙伴可以先做简单了解，后面我们再逐个介绍它们之间的流转过程。</p><ul><li><p><strong>NONE 状态</strong>：Master 节点一切正常，没有 failover 发生。</p></li><li><p><strong>WAIT_START 状态</strong>：Master 节点客观下线，且符合 failover 的各项条件，等待其 Leader Sentinel 进行 failover。</p></li><li><p><strong>SELECT_SLAVE 状态</strong>：Leader Sentinel 会选择一个 Slave 晋级为 Master。</p></li><li><p><strong>SEND_SLAVEOF_NOONE 状态</strong>：Leader Sentinel 会向选出的 Slave 发送 <code>SLAVEOF NO ONE</code> 命令，使其变更为 Master。</p></li><li><p><strong>WAIT_PROMOTION 状态</strong>：等待 Slave 晋升为 Master。</p></li><li><p><strong>RECONF_SLAVES 状态</strong>：向其他 Slave 发送 <code>SLAVEOF</code> 命令，使它们成为新一任 Master 的 Slave。</p></li><li><p><strong>UPDATE_CONFIG 状态</strong>：Sentinel 开始监听新的 Master。</p></li></ul><p>了解完 failover_state 各个状态的含义之后，下面我们就结合上面的流程图来详细分析每次状态转换的具体实现。</p><h2 id="none→wait-start" tabindex="-1">NONE→WAIT_START <a class="header-anchor" href="#none→wait-start" aria-label="Permalink to &quot;NONE→WAIT_START&quot;">​</a></h2><p>在上一讲中，我们已经详细分析了 Sentinel 对 Master 节点的状态检查原理，在完成该检查之后，Sentinel 会调用 <code>sentinelStartFailoverIfNeeded() 函数</code>检查是否需要对该 Master 节点进行 failover 操作，其中主要检查下面三点：</p><ul><li>确认该 Master 处于客观下线状态；</li><li>确认该 Master 处于未进入 failover 的状态，也就是没有 SRI_FAILOVER_IN_PROGRESS 标记；</li><li>确认该 Master 上次 failover 操作距今已经超过了两个 failover 超时的窗口，默认一个 failover 超时窗口为 3 分钟。</li></ul><p>同时满足上面三个条件时，Sentinel 会调用 <code>sentinelStartFailover() 函数</code>开启该 Master 的 failover 流程，该函数主要是设置下面的状态字段。</p><ul><li><p>首先，将 Master 的 failover_state 字段设置为 WAIT_START 状态，等待 failover 操作开始。</p></li><li><p>然后，在 Master 的 flags 字段中设置 SRI_FAILOVER_IN_PROGRESS 标记，表示该 Master 进入 failover 的状态中。</p></li><li><p>接下来，递增 master-&gt;failover_epoch 字段，进入下一个 epoch。</p></li><li><p>之后，更新 master-&gt;failover_start_time 字段记录当前时间，作为 failover 的启动时间戳。</p></li><li><p>最后，向 +new-epoch 频道发送消息（包含新的 epoch 值），向 +try-failove 频道发送消息（包含 Master 节点的信息）。</p></li></ul><p>下图说明了 NONE 状态切换到 WAIT_START 状态的关键变化：</p><p><img src="https://p1-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/504ccc98bb8c45a2a4e9e65c23fd28b9~tplv-k3u1fbpfcp-watermark.image?" alt="image.png" loading="lazy"></p><h2 id="wait-start→select-slave" tabindex="-1">WAIT_START→SELECT_SLAVE <a class="header-anchor" href="#wait-start→select-slave" aria-label="Permalink to &quot;WAIT_START→SELECT_SLAVE&quot;">​</a></h2><p>根据前面 failover_state 状态的转换图我们知道，Master 进入 WAIT_START 之后会在下一次定时任务中由 <code>sentinelFailoverWaitStart() 函数</code>将 failover_state 转移到 SELECT_SLAVE 状态。</p><p><strong>sentinelFailoverWaitStart() 函数的核心功能是确认自身是否为 Leader Sentinel</strong>，这里会迭代 master-&gt;sentinels 字典（也就是监听宕机 Master 节点的 Sentinel 对应的 sentinelRedisInstance 实例），统计所有 Sentinel 节点的投票结果（即统计其 leader、leader_epoch 字段值）。如果当前 Sentinel 得到了半数以上的投票，则当前 Sentinel 节点为 Leader 节点，否则表示其他 Sentinel 节点得到过半数的投票，成为 Leader 节点，或者没有任何 Sentinel 节点拿到半数以上投票，此时会等待下次投票才能产生 Leader Sentinel。</p><p>当前 Sentinel 节点成为 Leader 之后，会将 failover_state 状态推进为 SELECT_SLAVE，同时向 +elected-leader、+failover-state-select-slave 频道发送消息广播 Leader Sentinel 的选举结果以及 failover_state 状态的迁移信息。下图展示了前文示例中 Sentinel1 成为 Leader Sentinel 的场景：</p><p align="center"><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/a941190d80e2451fa0deaf14f139af5f~tplv-k3u1fbpfcp-watermark.image?" alt="image.png"></p><p>如果当前 Sentinel 节点未成为 Leader，那就会去定期检查正在执行的选举操作是否超时（默认超时时间为 10 秒），如果发现其超时，会将 Master 节点的 failover_state 状态以及 flags 中的相关标记位清空掉，之后重新检查 Master 节点的状态。</p><h2 id="select-slave→send-slaveof-noone" tabindex="-1">SELECT_SLAVE→SEND_SLAVEOF_NOONE <a class="header-anchor" href="#select-slave→send-slaveof-noone" aria-label="Permalink to &quot;SELECT_SLAVE→SEND_SLAVEOF_NOONE&quot;">​</a></h2><p>在当前 Sentinel 节点成为 Leader 之后，会开始从 Slave 节点中选择一个成为新的 Master 节点，这部分选择逻辑位于 <code>sentinelSelectSlave() 函数</code>中。该函数核心原理分为两部分，一个是根据 master-&gt;slaves 中记录的 Slave 状态对 Slave 进行<strong>过滤</strong>，二是对符合条件的 Slave 进行<strong>排序</strong>，最终<strong>选取</strong>最优的 Slave 成为新一任 Master 节点，我们称之为“Promoted Slave”。</p><p>下面是 sentinelSelectSlave() 函数过滤 Slave 节点时的关键步骤。</p><ol><li><p>首先，检查 Slave 节点是否处于下线，即检查 slave-&gt;flags 中是否包含 SRI_S_DOWN 或 SRI_O_DOWN 标记位。</p></li><li><p>然后，检查 Slave 节点与当前 Sentinel 节点是否连通，即检查表示 Slave 与当前 Sentinel 之间 intanceLink 连接的 disconnected 字段值。</p></li><li><p>之后，检查最近一次收到 Slave 节点 PING 响应的时间距今是否超过 5 秒。</p></li><li><p>接下来，检查最近一次请求 Slave 节点的 INFO 命令是否超时，具体超时时间有 3 秒、5 秒两个选项，具体选择哪个值，是根据 Master 节点处于主观下线，还是客观下线状态决定的。</p></li><li><p>最后，检查 Slave 主从复制连接的断开时长是否过长，默认是 10 倍的主观下线时间窗口，也就是 5 分钟。Master 下线的话，主从复制的网络连接必然是断开的。但是 Slave 要与 Master 的数据尽可能保持一致的话，主从复制连接最好是在 Master 下线的时候才断开，所以这里会检查 Slave 主从复制连接断开的时长。</p></li></ol><p>通过上述检查的 Slave 节点会被记录到一个数组中，然后<strong>通过 qsort() 函数对数组进行排序</strong>，排序后数组中的第一个 Slave 节点，就是要升级为 Master 的 Slave 节点，我们也称之为 “Promoted Slave 节点”。这里比较 Slave 节点的<strong>排序方式位于 compareSlavesForPromotion() 函数</strong>中，它会依次按照 <strong>Slave 的优先级</strong>、<strong>Replication Offset</strong> 以及 <strong>runId</strong> 对 Slave 节点进行排序。</p><p>选出 Promoted Slave 节点之后，Leader Sentinel 会为 Promoted Slave 节点添加 SRI_PROMOTED 标识，然后将 Master 的 failover_state 状态切换为 SEND_SLAVEOF_NOONE 状态，如下图所示。最后向 +selected-slave、+failover-state-send-slaveof-noone 频道发送通知并执行相应脚本。</p><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/5f80b6bce9e0493782f134df2b7afc20~tplv-k3u1fbpfcp-watermark.image?" alt="image.png" loading="lazy"></p><h2 id="send-slaveof-noone→wait-promotion" tabindex="-1">SEND_SLAVEOF_NOONE→WAIT_PROMOTION <a class="header-anchor" href="#send-slaveof-noone→wait-promotion" aria-label="Permalink to &quot;SEND_SLAVEOF_NOONE→WAIT_PROMOTION&quot;">​</a></h2><p>完成上述 Promoted Slave 节点的筛选之后，Leader Sentinel 会在 <code>sentinelFailoverSendSlaveOfNoOne() 函数</code>中向 Promoted Slave 节点发送 <code>SLAVEOF NO ONE</code> 命令，使其提升成为 Master 节点。<strong>这里实际上是启动了一个 Redis 事务</strong>，依次发送下面的命令：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MULTI</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       // 启动事务</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SLAVEOF NO ONE</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              // 让Promoted Slave节点提升为Master</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG REWRITE</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              // 重写Promoted Slave节点的配置文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLIENT  KILL TYPE normal</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 关闭连接Promoted Slave节点的所有客户端</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLIENT  KILL TYPE pubsub</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 关闭Promoted Slave节点上所有PUBSUB</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXEC</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        // 执行事务</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>发送完上述命令之后，Leader Sentinel 并不关心其返回值，而是通过后续 INFO 命令的响应，判断 SLAVEOF NO ONE 命令是否执行成功。最后，sentinelFailoverSendSlaveOfNoOne() 函数会将 Master 节点的 failover_state 状态推进为 WAIT_PROMOTION，并在 +failover-state-wait-promotion 频道发送通知。核心操作如下图所示：</p><p><img src="https://p1-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/884bdb2bce3d475aafa8b7ee656be819~tplv-k3u1fbpfcp-watermark.image?" alt="image.png" loading="lazy"></p><p>Leader Sentinel 节点在执行后续定时任务时，发现处于 WAIT_PROMOTION 状态的 Master 节点时，会检查其 failover 操作是否超时，如果超时，会将 failover_state 状态以及相关标记位重置。后续 failover_state 的推进将在 INFO 响应处理函数中完成。</p><h2 id="wait-promotion→reconf-slaves" tabindex="-1">WAIT_PROMOTION→RECONF_SLAVES <a class="header-anchor" href="#wait-promotion→reconf-slaves" aria-label="Permalink to &quot;WAIT_PROMOTION→RECONF_SLAVES&quot;">​</a></h2><p>前面我们介绍 INFO 响应对应的回调函数时，已经详细分析了 <strong>sentinelRefreshInstanceInfo() 函数</strong>对 INFO 响应的解析逻辑，这里我们再来看看该函数后半部分与 failover 相关的内容。</p><p>如果发现对端节点的 INFO 响应中 role 信息发生变化（也就是从 Master 变成了 Slave 或是从 Slave 变成了 Master），Sentinel 会使用对应的 role_reported 字段记录最新的 role，使用 role_reported_time 字段记录 role 变更的时间戳。</p><p>接下来，Sentinel 会根据对端节点的具体状态，进入不同的分支，主要分为三大类：对端节点从 Master 切换为 Slave、从 Slave 切换到 Master 或是始终为 Slave。</p><p>如果对端节点<strong>从 Master 切换为 Slave</strong>，一般是因为当前 Sentinel 访问不到该节点，这里不用做任何处理。</p><p>如果对端节点是<strong>从 Slave 切换到 Master</strong>，则需要分两种情况来看了。</p><p><strong>第一种情况，检查此次切换是否由 failover 操作触发</strong>。如果当前处理 INFO 响应的是 Leader Sentinel 节点的话，那么 Leader Sentinel 就能够检查出对端节点是否为 failover 操作中选出的 Promoted Slave 节点，以及当前 Master 的 failover_state 和 flags 是否处于 failover 的状态。</p><p>当确认是 Promoted Slave 切换成 Master 之后，会紧接前文介绍的 failover 处理流程将 Master 的 failover_state 状态推进为 RECONF_SLAVES 状态，递增其 config_epoch 值，然后将持久化 sentinel.conf 配置文件，最后重置所有节点的 last_pub_time 时间戳，尽快发送 hello 消息，将修改后的配置传递出去。</p><p>另外，Leader Sentinel 在得知 Promoted Slave 成功切换成 Master 之后，还会自动调用 client_reconfig_script 脚本，该脚本的参数格式如下：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">master</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">role</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">state</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ip</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ip</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>我们可以通过该脚本进行一些自动运维的操作，例如，在使用 Sentinel + VIP 的场景中，我们可以编写一个 VIP 切换脚本，并通过 <code>sentinel client-reconfig-script &lt;master-name&gt; &lt;script-path&gt;</code> 命令进行配置。当 Master 发生 failover 的时候，就可以<strong>通过该 VIP 切换脚本将 VIP 漂移到新一任 Master 上</strong>，继续对外提供服务了。</p><p>下图展示了 Leader Sentinel 节点得知 Promoted Slave 提升为 Master 的核心操作：</p><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/cb22bc2c0eb549c4a1bb2ae87acac936~tplv-k3u1fbpfcp-watermark.image?" alt="image.png" loading="lazy"></p><p><strong>第二种情况，检测此次切换是否为异常切换</strong>。Sentinel 会检查对端节点以及其 Master 的状态，如果 Master 一切正常，但是其下一个 Slave 节点突然切换为 Master，即为异常切换。这里检查的条件如下：</p><ul><li>对端节点的 Master 节点正常在线，即对端节点的 Master 能够正常响应 INFO 命令，且 INFO 响应中依旧上报自己为 Master；</li><li>对端节点最近（8 秒内）没有发生下线；</li><li>对端 Slave 节点长时间上报自己为 Master，防止误报。</li></ul><p>上述三项检查都通过之后，Sentinel 会认为这是一次异常切换，此时，Sentinel 会向对端节点发送 <code>SLAVEOF</code> 命令，将其重新变为 Slave 节点。</p><p>如果对端<strong>始终为 Slave 节点</strong>，但是其复制的 Master 节点发生了变更，可能是异常切换，也可能是 failover 操作导致的。此时 Sentinel 会进行异常切换的检查，检查条件前文已述，这里不再重复。如果判定为异常切换，则 Sentinel 会发送 <code>SLAVEOF</code> 命令，让其重新复制原来的 Master 节点。如果不是异常切换，则当前 Sentinel 不进行任何处理，而是后续由 Leader Sentinel 节点进行处理，让其成为新一任 Master 节点的 Slave。</p><p>sentinelRefreshInstanceInfo() 函数最后还有一个分支，与 failover 后续的流程强相关，这里暂时按下不表，后面会展开分析。</p><h2 id="reconf-slaves→update-config" tabindex="-1">RECONF_SLAVES→UPDATE_CONFIG <a class="header-anchor" href="#reconf-slaves→update-config" aria-label="Permalink to &quot;RECONF_SLAVES→UPDATE_CONFIG&quot;">​</a></h2><p>在 Promoted Slave 节点提升为 Master 之后，Leader Sentinel 节点会像剩余的 Slave 节点变成Promoted Slave 的 Slave 节点，为了实现该效果，会向这些节点发送 SLAVEOF 命令，这部分逻辑位于 <strong>sentinelFailoverReconfNextSlave() 函数</strong>。默认 Leader Sentinel 会<code>串行</code>处理剩余 Slave 节点，即待一个 Slave 节点处理完 SLAVEOF 命令之后，才会向下一个 Slave 节点发送 SLAVEOF 命令，我们也可以通过 sentinel parallel-syncs 配置修改发送 SLAVEOF 命令的并发值。当 Leader Sentinel 节点向 Slave 节点成功发送 SLAVEOF 命令之后，会在其 flags 字段中设置 SRI_RECONF_SENT 位进行标记。</p><p>下图简单总结了一下这部分的核心操作：</p><p><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/6ef0fa741f9244cc8759e950bbc9883d~tplv-k3u1fbpfcp-watermark.image?" alt="image.png" loading="lazy"></p><p>完成 SLAVEOF 命令的发送之后，我们再跳转到 sentinelRefreshInstanceInfo() 函数（即 INFO 命令处理逻辑）的最后一个分支，这个分支的核心逻辑就是 <strong>Leader Sentinel 用来监控收到 SLAVEOF 命令的 Slave 有没有切换 Master</strong>。</p><p>在该分支中，Leader Sentinel 会先确认 Slave 节点设置了 SRI_RECONF_SENT 标记（即 Leader Sentinel 向其发送过 SLAVEOF 命令），然后检查 INFO 响应中返回的 Master 地址与 Promoted Slave 节点的地址是否一致，如果一致的话，会将该 Slave 节点的SRI_RECONF_SENT 标记更新为 SRI_RECONF_INPROG 标记，表示该 Slave 节点正在切换 Master 节点。</p><p>接下来，Leader Sentinel 会通过 INFO 响应中的 master_link_status 行，检查该 Slave 节点与新的 Master 的主从复制连接是否已建立成功，如果已建连，则将该 Slave 节点的 SRI_RECONF_INPROG 标记更新为 SRI_RECONF_DONE，表示 Slave 节点切换 Master 节点完成。</p><p>下图简单总结了这部分的核心操作：</p><p><img src="https://p1-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/100c33ccd85e4db6a73f8458db615753~tplv-k3u1fbpfcp-watermark.image?" alt="image.png" loading="lazy"></p><p>到此为止，整个 INFO 响应处理逻辑我们分三部分全部介绍完了。</p><p>接下来我们回到 sentinelFailoverReconfNextSlave() 函数继续分析。在发送完 SLAVEOF 命令之后，Leader Sentinel 节点后续定时任务中会周期性调用 sentinelFailoverDetectEnd() 函数，检查这些收到 SLAVEOF 的 Slave 节点是否已经到达 SRI_RECONF_DONE 状态（即检查 Slave 是否都开始复制新 Master），如果全部到达，则表示 failover 操作已经正常结束。如果没有全部到达 SRI_RECONF_DONE 状态，则检查 failover 操作是否超时，如果超时，会重新向超时的 Slave 再次发送 SLAVEOF 命令，然后结束 failover 操作。</p><p>但无论 failover 正常完成还是超时完成，此时都会将上一任 Master 的 failover_state 状态推进为 UPDATE_CONFIG，表示即将开始通知 Sentinel 节点监听新一任 Master。</p><h2 id="update-config→none" tabindex="-1">UPDATE_CONFIG→NONE <a class="header-anchor" href="#update-config→none" aria-label="Permalink to &quot;UPDATE_CONFIG→NONE&quot;">​</a></h2><p>当上一任 Master 进入 UPDATE_CONFIG 状态之后，Leader Sentinel 节点在下次定时任务执行时，会进入 <strong>sentinelResetMasterAndChangeAddress() 函数</strong>，完成下面三个核心步骤。</p><ul><li>更新 Master 节点地址，即将 Master sentinelRedisInstance 中记录的地址切换成新一任 Master 节点的地址。</li><li>按照地址从 slaves 字典中删除新一任 Master 对应的 sentinelRedisInstance 实例，毕竟它之前也是一个 Slave 节点。</li><li>将 Master sentinelRedisInstance 的 failover_state 状态切换为 NONE，表示 Sentinel 已经开始监控新一任 Master 节点。</li></ul><p>完成这些操作之后，Leader Sentinel 会持久化自己的 sentinel.conf 配置文件，保存新一任 Master 的信息，还会向 +switch-master 频道发送新旧两任的 Master 地址。</p><p>在该 Leader Sentinel 后续发送 hello 消息的时候，就会携带新一任 Master 的地址，其他 Sentinel 收到该消息之后，也会执行 sentinelResetMasterAndChangeAddress() 函数完成 Master 的切换以及状态重置逻辑。下图展示了 UPDATE_CONFIG 状态下 Leader Sentinel 的核心操作：</p><p><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/76a84c3d9d8e49f1ba0b01cd66be3649~tplv-k3u1fbpfcp-watermark.image?" alt="image.png" loading="lazy"></p><p>到此为止，Sentinel 的 failover 逻辑就彻底执行完毕了。</p><h2 id="sentinel-客户端核心原理" tabindex="-1">Sentinel 客户端核心原理 <a class="header-anchor" href="#sentinel-客户端核心原理" aria-label="Permalink to &quot;Sentinel 客户端核心原理&quot;">​</a></h2><p>通过前文的介绍，我们了解了 Sentinel Failover 的核心原理，不过你可能会产生一个疑问：如果发生了 Failover，Redis Client 是如何知道新一任 Master 主库的地址呢？</p><p><strong>一种方式是使用 VIP + client_reconfig_script 脚本的方式</strong>，这样客户端看到的始终是 VIP，Sentinel 在 failover 完成时漂移 VIP 到新一任 Master，客户端重新建连即可。这种方式会引入 VIP 这一额外组件，还要额外编写 client_reconfig_script 脚本，增加了运维成本。</p><p><strong>另一种方式是将查找新一任 Master 的能力封装到 Redis 客户端</strong>，在 Redis 官网中提供了<a href="https://redis.io/docs/reference/sentinel-clients/" target="_blank" rel="noreferrer">一个 Sentinel Client 的实现指南</a>，其中写明了实现 Sentinel Client 的核心原理，这里我们展开说明一下。</p><p>Sentinel Client 需要从其已知的 Sentinel 节点集合中，筛选出一个可用的 Sentinel 节点，如下所示：</p><p align="center"><img src="https://p1-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/e50ceee56d1245738d8ebe69a0fbe48b~tplv-k3u1fbpfcp-watermark.image?" alt="image.png"></p><p>通过前文的介绍我们知道，Sentinel 之间会 hello 频道交互信息，从而得知多个 Redis 主从复制集群的全部网络拓扑结构，所以 Sentinel Client 只需要找到一个可用的 Sentinel 节点即可。</p><p>接下来，Sentinel Client 会将向 Sentinel 发送 sentinel get-master-addr-by-name master-name 命令。通过前面的介绍我们知道一个 master-name 可以唯一定位一个 Master 节点（其 Slave 节点也自然可以查询到了），Sentinel 在收到 sentinel sentinel get-master-addr-by-name 命令之后，会根据 master-name 查询 sentinel.master 字典，获取对应 Master 节点的地址，如果该 Master 处于 Failover 的状态，则返回 Promoted Slave 节点的地址。</p><p>最后，Sentinel Client 会向 Master 节点发送数据 ROLE 命令或 INFO 命令，并根据返回值确认 Sentinel 返回的节点确实是 Master 节点。确认之后，Client 就可以与 Master 节点建立连接，执行后续正常的读写命令了。另外，Sentinel Client 会订阅各个 Sentinel 节点的 +switch-master 频道，在当出现 failover 操作的时候，Sentinel Client 能够第一时间得到新一任 Master 的地址并尝试进行连接，从而连接新的 Master 节点。</p><p>即使 Sentinel Client 未及时收到 +switch-master 频道的消息通知，在 Master 节点下线的时候，Sentinel Client 与 Master 之间的连接会自然断开，Sentinel Client 也会自动重新执行上述逻辑，查找最新的 Master 节点。如果 Sentinel Client 查找到的 Sentinel 节点持有的 Redis 节点拓扑并不是最新的，导致其返回的 Master 节点地址错误，Sentinel Client 也可以通过 ROLE 命令或是 INFO 命令确认该节点并非真正的 Master 节点，从而重试上述逻辑查找新的 Sentinel 节点询问 Master 节点。</p><p>在读写分离的场景中，客户端可能希望连接 Slave 节点，此时 Sentinel Client 会向 Sentinel 发送 sentinel replicas master-name 命令得到 Slave 节点列表，然后 Sentinel Client 选择合适的 Slave 节点进行连接。当出现 failover 的时候，Leader Sentinel 会向所有 Slave 节点发送 CLIENT KILL type normal 命令断开全部客户端连接，客户端之后会重新执行上面的流程，选择新的 Slave 节点进行连接。</p><p>在 Java 中常用的 Redis 客户端是 Jedis，它基本上就是按照上述方案进行实现的，相关的实现位于 JedisSentinelPool 中，这里就不再展开介绍了。其他 Redis 不同客户端的具体实现可能与上面描述的方案大同小异，这里就不再一一展开赘述了，感兴趣的同学可以查找相关资料进行学习。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本节承接上一节完成了对 Redis Sentinel 的介绍，本节重点介绍了 Sentinel 自动故障转移相关的内容。</p><ul><li>首先，我们说明了引入 Sentinel 的核心目的之一就是实现 Redis 主从集群自动故障转移。</li><li>然后，我们介绍了 Sentinel 模式中故障转移的状态机，以及各个状态的具体含义。</li><li>接下来，我们详细梳理了 Sentinel 故障转移的流程，分析了每一次状态转换的底层实现。</li><li>最后，还说明了客户端侧如何支持 Sentinel 模式的自动故障转移。</li></ul><p>如果你在学习过程中有什么不懂的地方，或者有什么问题，欢迎你在留言区与我分享，我们一起交流、一起进步。</p>`,90)])])}const g=a(s,[["render",l]]);export{h as __pageData,g as default};
